SYSTEM = """Sen bir yardımcı asistansın. Yalnızca aşağıdaki bağlamdan cevap ver.
Eğer cevap bağlamda yoksa 'bilmiyorum' de. Cevabını sonunda [1], [2] gibi kaynak numaraları ile destekle."""

def build_prompt(question: str, context_chunks):
    ctx = "

".join(f"[{i+1}] {c}" for i, c in enumerate(context_chunks))
    return f"{SYSTEM}

Bağlam:
{ctx}

Soru: {question}"

def recall_at_k(retrieved_ids, relevant_ids, k=5):
    if k <= 0:
        raise ValueError("k must be positive")
    relevant = set(relevant_ids)
    if not relevant:
        raise ValueError("Provide labeled relevant chunk IDs")
    return len(set(retrieved_ids[:k]) & relevant) / len(relevant)

# Synthetic IDs: 1 of 2 relevant chunks retrieved => 0.5
