npm i @mlc-ai/web-llm

import { CreateMLCEngine } from "@mlc-ai/web-llm";

const initProgressCallback = (p: any) => console.log("init:", p);

const engine = await CreateMLCEngine("Llama-3.2-1B-Instruct-q4f16_1-MLC", {
  initProgressCallback,
});

const reply = await engine.chat.completions.create({
  messages: [{ role: "user", content: "Merhaba, kendini tanıt." }],
});
console.log(reply.choices[0].message.content);

const stream = await engine.chat.completions.create({
  stream: true,
  messages: [{ role: "user", content: "Bana kısa bir hikaye anlat." }],
});

for await (const chunk of stream) {
  const delta = chunk.choices[0]?.delta?.content ?? "";
  if (delta) document.body.append(delta);
}
